import java.util.*;

class Solution {
    public List<Integer> inorderTraversal(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        Deque<TreeNode> st = new ArrayDeque<>();
        TreeNode cur = root;
        while (cur != null || !st.isEmpty()) {
            while (cur != null) { // slide as far left as possible
                st.push(cur);
                cur = cur.left;
            }
            cur = st.pop();       // left side finished
            out.add(cur.val);     // record the node
            cur = cur.right;      // now handle its right side
        }
        return out;
    }
}

